// Timing and size of the importFacts member (REQ-polaris-generation-034 version 2.39, syzygy-3efd.89 review 1 note 9).
// Run from the worktree root: npx vite-node <this file> -- <gitDir> <commit> <out.json>
import { readFileSync, writeFileSync } from 'node:fs';
import * as path from 'node:path';
import { performance } from 'node:perf_hooks';
import { openPinnedObjectReader } from '/home/orca/orca/projects/syzygy/.worktrees/parallel-agents/syzygy-3efd.89/packages/polaris-dossier/src/git-object-reader.js';
import { IMPORT_BLOB_LIMIT, deriveImportFacts, type ImportFacts } from '/home/orca/orca/projects/syzygy/.worktrees/parallel-agents/syzygy-3efd.89/packages/polaris-dossier/src/import-facts.js';
import { MANIFEST_BLOB_LIMIT, deriveManifestFacts } from '/home/orca/orca/projects/syzygy/.worktrees/parallel-agents/syzygy-3efd.89/packages/polaris-dossier/src/manifest-facts.js';
import { buildDossierScreen } from '/home/orca/orca/projects/syzygy/.worktrees/parallel-agents/syzygy-3efd.89/packages/polaris-dossier/src/screen.js';

const [gitDir, commit, out, root] = process.argv.slice(-4);
const policy = new Uint8Array(readFileSync(path.join(root!, '.syzygy/governance/policies/POLARIS-DOSSIER-DECLARED-SOURCE-POLICY-v2.json')));
const load = buildDossierScreen(policy, true, { repository: 'repository:measure', commit: commit! }, 'public');
if (!load.ok) throw new Error(load.why);
const screen = load.screen;
const memberBytes = (member: ImportFacts): number => new TextEncoder().encode(JSON.stringify(member, null, 2).replace(/\n/gu, '\n  ')).length;

const runs: unknown[] = [];
for (let k = 0; k < 3; k++) {
  const lister = openPinnedObjectReader({ gitDir: gitDir!, revision: commit! });
  const entries = await lister.listTree();
  const manifestReader = openPinnedObjectReader({ gitDir: gitDir!, revision: commit!, maxObjectBytes: MANIFEST_BLOB_LIMIT });
  const manifestFacts = await deriveManifestFacts({ entries, screen, consented: null, read: async (p) => (await manifestReader.readBlobs([p]))[0]! });
  const reader = openPinnedObjectReader({ gitDir: gitDir!, revision: commit!, maxObjectBytes: IMPORT_BLOB_LIMIT });
  const t0 = performance.now();
  const member = await deriveImportFacts({ entries, screen, consented: null, manifestFacts, read: async (p) => (await reader.readBlobs([p]))[0]! });
  const ms = performance.now() - t0;
  if (member.state !== 'derived') throw new Error('member unknown');
  runs.push({ milliseconds: Math.round(ms), memberBytes: memberBytes(member), entries: entries.length, candidates: member.candidates, scanned: member.scanned,
    incomplete: member.incomplete, unknown: member.unknown, setApart: member.setApart, statements: member.statements, outsideGrammar: member.outsideGrammar,
    edges: member.edges.length, facts: member.facts.length, factsNotListed: member.factsNotListed, coverage: member.coverage });
}
writeFileSync(out!, `${JSON.stringify({ gitDir: path.basename(path.dirname(gitDir!)), commit, runs }, null, 2)}\n`);
